contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint sent) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sent)); require(sent <= 1000000000000000000000000000000);
        require(address(this).balance >= sent, "insufficient test balance");

        bool reverted;
        c.play{value: sent}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        assert(
            (sent != 10 && reverted) ||
            (sent == 10 && !reverted && (potAfter == 0 || potAfter == 10))
        );
    }

    receive() external payable {}
}

