pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 sent) internal {
        sent = bound(sent, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sent);
        bool reverted;
        try c.play{value: sent}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue((sent != 10 && reverted) ||
            (sent == 10 && !reverted && (potAfter == 0 || potAfter == 10)));
    }

    function testFuzz_run(uint256 sent) public {
        _run(sent);
    }

    receive() external payable {}
}
